import {applySeasonalAppearance,worldSeason} from './seasonal-appearance.js';
import * as THREE from 'three';
import {timeOfDay,SKY_MOODS} from './time-of-day.js';
import {drawSky,skyMotifLayout,drawSkyBand} from './sky-draw.js';
import {ensureHandwriting} from './font-ready.js';
export function applyEnvironmentMood(root,mood){root?.traverse(o=>{if(o.userData.timeOfDayLight)o.intensity=mood.glow*(o.userData.nightIntensity??2);if(!o.userData.nightWindow&&!o.userData.nightLamp)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!m?.color||!m.emissive)return;m.userData.dayColor??=m.color.getHexString();m.color.set(mood.glow?'#f5dbaa':'#'+m.userData.dayColor);m.emissive.set('#ffd28a');m.emissiveIntensity=mood.glow*(o.userData.nightLamp?1.2:.7);}});}
export function applyMoodLights({hemi,sun,fill},mood){hemi.intensity=mood.ambient*.72;hemi.color.set(mood.id==='night'?'#d4e2ff':'#fbfff3');hemi.groundColor.set(mood.id==='night'?'#8196a6':'#aab39b');sun.color.set(mood.sun);sun.intensity=mood.sunIntensity*.85;fill.intensity=mood.fill*.65;}
function skyWaterMaterial(color){return new THREE.ShaderMaterial({name:'Horizon sea',transparent:true,depthWrite:false,toneMapped:false,uniforms:{waterColor:{value:new THREE.Color(color)},resolution:{value:new THREE.Vector2(1,1)},horizon:{value:new THREE.Vector2(.32,.44)}},vertexShader:'void main(){gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'uniform vec3 waterColor;uniform vec2 resolution;uniform vec2 horizon;void main(){float y=1.0-gl_FragCoord.y/max(resolution.y,1.0);float alpha=smoothstep(horizon.x,horizon.y,y);gl_FragColor=vec4(waterColor,alpha);\n#include <colorspace_fragment>\n}'});}
/** One owned sky texture. Indoor/photo lighting stays bright and photo sessions freeze the game frame. */
export function createSkyView({scene,hemi,sun,fill,stage,renderCanvas,onClock=()=>{}}){
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');const texture=ctx?new THREE.CanvasTexture(canvas):null;if(texture)texture.colorSpace=THREE.SRGBColorSpace;let alive=true,dirty=true,lastKey='',lastRead=-Infinity,lastCalendarDay=null,state=null,lastClock='',water=null,horizon=[.32,.44];
 ensureHandwriting('북두칠성 오리온자리 한국 시간 아침 낮 저녁 밤').then(()=>{if(alive)dirty=true;});
 // KST has no DST: a numeric day key catches midnight inside the 1s throttle
 // without adding an Intl/string allocation to ordinary steady frames.
 function update({roomId,view,date=new Date(),layout=null}={}){if(!alive||!(date instanceof Date)||!Number.isFinite(date.getTime()))return state;if(!layout&&texture&&state&&['courtyard','park','playground','sportsField','amusementIsland','observatoryIsland','coasterGarden','villageHarbor','villageAirport','amusementAirport'].includes(roomId)&&scene.background!==texture)scene.background=texture;const now=date.getTime(),calendarDay=Math.floor((now+9*60*60*1000)/86400000),width=Math.max(1,Math.round(stage.clientWidth)),height=Math.max(1,Math.round(stage.clientHeight)),stageTop=stage.getBoundingClientRect?.().top??0,overlays=[stage.querySelector?.('.scene-tools'),stage.querySelector?.('.mission-pill'),document.querySelector?.('.topbar')].filter(el=>el&&el.getClientRects().length),safeTop=Math.max(0,...overlays.map(el=>el.getBoundingClientRect().bottom-stageTop))+10,identity=`${JSON.stringify(layout)}:${safeTop}:${roomId}:${view?.root.uuid??''}:${width}:${height}:${document.body?.dataset.cameraMode??'walk'}`;if(water){water.uniforms.resolution.value.set(renderCanvas.width,renderCanvas.height);}if(calendarDay===lastCalendarDay&&!dirty&&identity===lastKey.split('|')[0]&&Math.abs(now-lastRead)<1000)return state;lastRead=now;const season=calendarDay===lastCalendarDay&&state?state.season:worldSeason(date),seasonChanged=season!==state?.season;lastCalendarDay=calendarDay;state=timeOfDay(date);state.season=season;applySeasonalAppearance(view?.root,season);if(state.clock!==lastClock||seasonChanged){lastClock=state.clock;onClock(state);}
  const outdoor=['courtyard','park','playground','sportsField','amusementIsland','observatoryIsland','coasterGarden','villageHarbor','villageAirport','amusementAirport'].includes(roomId),mood=outdoor?state:SKY_MOODS.day,key=identity+'|'+mood.id;if(key===lastKey&&!dirty)return state;lastKey=key;dirty=false;applyMoodLights({hemi,sun,fill},mood);applyEnvironmentMood(view?.root,mood);
  if(outdoor&&layout){const band=stage.querySelector?.('#overview-sky'),context=band?.getContext('2d');if(context){const dpr=Math.min(2,globalThis.devicePixelRatio||1),{width:w,height:h}=layout.skyRect;band.width=Math.round(w*dpr);band.height=Math.round(h*dpr);context.setTransform(dpr,0,0,dpr,0,0);drawSkyBand(context,{width:w,height:h,mood,compact:layout.compact});}scene.background=new THREE.Color(mood.water);horizon=[-1,-.99];}else if(outdoor&&ctx){const scale=Math.min(1,1600/Math.max(width,height));canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);const motif=skyMotifLayout(canvas.width,canvas.height,safeTop*scale);horizon=motif.waterFade;drawSky(ctx,{width:canvas.width,height:canvas.height,mood,safeTop:safeTop*scale});texture.needsUpdate=true;scene.background=texture;}else scene.background=new THREE.Color(outdoor?mood.water:'#ddecf0');
  const sea=view?.root.getObjectByName('village.sea');if(sea){if(!sea.material.userData.horizonSea){sea.material.dispose();sea.material=skyWaterMaterial(mood.water);sea.material.userData.horizonSea=true;}water=sea.material;water.uniforms.waterColor.value.set(mood.water);water.uniforms.horizon.value.fromArray(horizon);water.uniforms.resolution.value.set(renderCanvas.width,renderCanvas.height);}else water=null;return state;
 }
 return {update,getState:()=>state?{id:state.id,label:state.label,clock:state.clock,timeZone:state.timeZone}:null,dispose(){if(!alive)return;alive=false;texture?.dispose();if(texture&&scene.background===texture)scene.background=new THREE.Color('#ddecf0');water=null;}};
}
